package claudecode

import (
	"context"
	"testing"

	"github.com/KogenAI/kogen-executor/executor"
)

// roundEndDetail runs one round against a fake Claude scripted by cfg and returns the detail of
// the executor/failed error the round ends with.
func roundEndDetail(t *testing.T, cfg fakeConfig) string {
	t.Helper()
	h := newHarness(t, cfg)
	s := h.startOK()
	_, err := s.Round(context.Background(), executor.Input{})
	return wantError(t, err, "executor/failed").Detail
}

func TestRoundSignalBeforeInitIsNamed(t *testing.T) {
	t.Parallel()
	got := roundEndDetail(t, fakeConfig{ExitBeforeStdin: true, Signal: 15, SignalAt: "before_stdin", Script: oneRound(finishRound)})
	want := "Claude Code was ended by signal 15 (terminated) before starting; stderr: fake claude: dying before reading the prompt"
	if got != want {
		t.Fatalf("detail %q, want %q", got, want)
	}
}

func TestRoundSignalWithoutResultIsNamed(t *testing.T) {
	t.Parallel()
	got := roundEndDetail(t, fakeConfig{Signal: 9, SignalAt: "after_init", Script: oneRound(finishRound)})
	want := "Claude Code was ended by signal 9 (killed) without a result"
	if got != want {
		t.Fatalf("detail %q, want %q", got, want)
	}
}

func TestRoundSignalAfterSuccessResultIsNamed(t *testing.T) {
	t.Parallel()
	got := roundEndDetail(t, fakeConfig{Signal: 9, SignalAt: "after_result", Script: oneRound(finishRound)})
	want := "Claude Code was ended by signal 9 (killed) after a success result"
	if got != want {
		t.Fatalf("detail %q, want %q", got, want)
	}
}

